import os
workdir = os.environ['TRAJECTORY_WORKDIR']
for root, dirs, files in os.walk(workdir):
    # skip memory
    dirs[:] = [d for d in dirs if d != 'memory']
    for f in files:
        p = os.path.join(root, f)
        try:
            sz = os.path.getsize(p)
        except OSError:
            sz = -1
        print(f"{sz:>10}  {p}")
